'use strict';

// MAIN //

/**
* Parses long command-line options used by harvester scripts.
*
* @param {Array} argv - argument vector without node/script entries
* @returns {Object} parsed options
*/
function parseArguments( argv ) {
	var options = {};
	var idx;
	var name;

	for ( idx = 0; idx < argv.length; idx += 1 ) {
		if ( !argv[ idx ].startsWith( '--' ) ) {
			throw new Error( 'Unexpected argument: ' + argv[ idx ] );
		}
		name = argv[ idx ].slice( 2 );
		if ( name === 'all' ) {
			options.all = true;
			continue;
		}
		if ( idx + 1 >= argv.length || argv[ idx + 1 ].startsWith( '--' ) ) {
			throw new Error( 'Missing value for --' + name );
		}
		options[ name.replaceAll( '-', '_' ) ] = argv[ idx + 1 ];
		idx += 1;
	}
	return options;
}


// EXPORTS //

module.exports = parseArguments;
